    /// <summary>
    /// OASIS provider for Gnosis Safe — multisig smart contract wallet.
    /// Safe addresses → Avatars (threshold, owners, nonce). Multisig transactions → Holons.
    /// API: https://safe-transaction-mainnet.safe.global
    /// </summary>
    public class SafeOASIS : OASISStorageProviderBase, IOASISStorageProvider, IOASISNETProvider
    {
        private readonly HttpClient _httpClient;
        private bool _isActivated;

        public SafeOASIS(string apiBase = "https://safe-transaction-mainnet.safe.global")
        {
            _httpClient = new HttpClient { BaseAddress = new Uri(apiBase) };
            _httpClient.DefaultRequestHeaders.Add("Accept", "application/json");
            ProviderName = "SafeOASIS";
            ProviderDescription = "Gnosis Safe Multisig Wallet Provider";
            ProviderType = new EnumValue<ProviderType>(Core.Enums.ProviderType.SafeOASIS);
            ProviderCategory = new EnumValue<ProviderCategory>(Core.Enums.ProviderCategory.StorageAndNetwork);
            ProviderCategories.Add(new EnumValue<ProviderCategory>(Core.Enums.ProviderCategory.Blockchain));
        }

        public override async Task<OASISResult<bool>> ActivateProviderAsync()
        {
            var result = new OASISResult<bool>();
            try
            {
                var response = await _httpClient.GetAsync("/api/v1/about/");
                if (response.IsSuccessStatusCode) { _isActivated = true; result.Result = true; result.Message = "SafeOASIS activated."; }
                else OASISErrorHandling.HandleError(ref result, $"SafeOASIS: API health check failed ({response.StatusCode}).");
            }
            catch (Exception ex) { result.Exception = ex; OASISErrorHandling.HandleError(ref result, ex.Message); }
            return result;
        }
        public override OASISResult<bool> ActivateProvider() => ActivateProviderAsync().Result;
        public override async Task<OASISResult<bool>> DeActivateProviderAsync() { _isActivated = false; return new OASISResult<bool>(true); }
        public override OASISResult<bool> DeActivateProvider() => DeActivateProviderAsync().Result;

        public override async Task<OASISResult<IAvatar>> LoadAvatarByProviderKeyAsync(string providerKey, int version = 0)
        {
            var result = new OASISResult<IAvatar>();
            try
            {
                var response = await _httpClient.GetAsync($"/api/v1/safes/{providerKey}/");
                if (response.IsSuccessStatusCode)
                {
                    var body = await response.Content.ReadFromJsonAsync<JsonElement>();
                    var avatar = new Avatar();
                    avatar.Username = providerKey;
                    avatar.MetaData["safe_address"] = providerKey;
                    avatar.MetaData["safe_nonce"] = body.TryGetProperty("nonce", out var n) ? n.ToString() : "0";
                    avatar.MetaData["safe_threshold"] = body.TryGetProperty("threshold", out var t) ? t.ToString() : "0";
                    avatar.MetaData["safe_owners"] = body.TryGetProperty("owners", out var o) ? o.ToString() : "[]";
                    avatar.MetaData["safe_version"] = body.TryGetProperty("version", out var v) ? v.GetString() : "";
                    result.Result = avatar;
                }
                else OASISErrorHandling.HandleError(ref result, $"SafeOASIS: Safe '{providerKey}' not found ({response.StatusCode}).");
            }
            catch (Exception ex) { result.Exception = ex; OASISErrorHandling.HandleError(ref result, ex.Message); }
            return result;
        }
        public override OASISResult<IAvatar> LoadAvatarByProviderKey(string providerKey, int version = 0) => LoadAvatarByProviderKeyAsync(providerKey, version).Result;

        public override async Task<OASISResult<IHolon>> LoadHolonAsync(string providerKey, bool loadChildren = true, bool recursive = true, int maxChildDepth = 0, bool continueOnError = true, bool loadChildrenFromProvider = false, int version = 0)
        {
            var result = new OASISResult<IHolon>();
            try
            {
                var response = await _httpClient.GetAsync($"/api/v1/multisig-transactions/{providerKey}/");
                if (response.IsSuccessStatusCode)
                {
                    var body = await response.Content.ReadFromJsonAsync<JsonElement>();
                    var holon = new Holon();
                    holon.Name = $"Safe Tx {providerKey[..Math.Min(10, providerKey.Length)]}...";
                    holon.MetaData["safe_tx_hash"] = providerKey;
                    holon.MetaData["safe_to"] = body.TryGetProperty("to", out var to) ? to.GetString() : "";
                    holon.MetaData["safe_value"] = body.TryGetProperty("value", out var v) ? v.GetString() : "0";
                    holon.MetaData["safe_data"] = body.TryGetProperty("data", out var d) && d.ValueKind != JsonValueKind.Null ? d.GetString() : "";
                    holon.MetaData["safe_is_executed"] = body.TryGetProperty("isExecuted", out var ie) ? ie.GetBoolean().ToString() : "false";
                    holon.MetaData["safe_confirmations"] = body.TryGetProperty("confirmations", out var conf) ? conf.ToString() : "[]";
                    result.Result = holon;
                }
                else OASISErrorHandling.HandleError(ref result, $"SafeOASIS: Transaction '{providerKey}' not found ({response.StatusCode}).");
            }
            catch (Exception ex) { result.Exception = ex; OASISErrorHandling.HandleError(ref result, ex.Message); }
            return result;
        }
        public override OASISResult<IHolon> LoadHolon(string providerKey, bool loadChildren = true, bool recursive = true, int maxChildDepth = 0, bool continueOnError = true, bool loadChildrenFromProvider = false, int version = 0)
            => LoadHolonAsync(providerKey, loadChildren, recursive, maxChildDepth, continueOnError, loadChildrenFromProvider, version).Result;

        public override async Task<OASISResult<IEnumerable<IHolon>>> LoadHolonsForParentAsync(string providerKey, HolonType type = HolonType.All, bool loadChildren = true, bool recursive = true, int maxChildDepth = 0, int curentChildDepth = 0, bool continueOnError = true, bool loadChildrenFromProvider = false, int version = 0)
        {
            var result = new OASISResult<IEnumerable<IHolon>>(); var holons = new List<IHolon>();
            try
            {
                var response = await _httpClient.GetAsync($"/api/v1/safes/{providerKey}/multisig-transactions/?limit=100");
                if (response.IsSuccessStatusCode)
                {
                    var body = await response.Content.ReadFromJsonAsync<JsonElement>();
                    var txs = body.TryGetProperty("results", out var r) ? r : body;
                    foreach (var tx in txs.EnumerateArray())
                    {
                        var holon = new Holon();
                        var safeTxHash = tx.TryGetProperty("safeTxHash", out var h) ? h.GetString() : "";
                        holon.Name = $"Safe Tx {(safeTxHash?.Length > 10 ? safeTxHash[..10] : safeTxHash)}...";
                        holon.MetaData["safe_tx_hash"] = safeTxHash;
                        holon.MetaData["safe_to"] = tx.TryGetProperty("to", out var to) ? to.GetString() : "";
                        holon.MetaData["safe_value"] = tx.TryGetProperty("value", out var v) ? v.GetString() : "0";
                        holon.MetaData["safe_is_executed"] = tx.TryGetProperty("isExecuted", out var ie) ? ie.GetBoolean().ToString() : "false";
                        holons.Add(holon);
                    }
                    result.Result = holons;
                }
                else OASISErrorHandling.HandleError(ref result, $"SafeOASIS: Get transactions failed ({response.StatusCode}).");
            }
            catch (Exception ex) { result.Exception = ex; OASISErrorHandling.HandleError(ref result, ex.Message); }
            return result;
        }
        public override OASISResult<IEnumerable<IHolon>> LoadHolonsForParent(string providerKey, HolonType type = HolonType.All, bool loadChildren = true, bool recursive = true, int maxChildDepth = 0, int curentChildDepth = 0, bool continueOnError = true, bool loadChildrenFromProvider = false, int version = 0)
            => LoadHolonsForParentAsync(providerKey, type, loadChildren, recursive, maxChildDepth, curentChildDepth, continueOnError, loadChildrenFromProvider, version).Result;

